const $=s=>document.querySelector(s);let view='properties',items=[];
const labels={properties:'Properties',posts:'Blog posts',enquiries:'Enquiries',finance:'Finance'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(x,k,d='')=>x[k]??d;
async function api(url,options={}){const r=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data}
function notify(text){const n=$('#notice');n.textContent=text;n.style.display='block';setTimeout(()=>n.style.display='none',3000)}
async function load(){try{items=await api(`/api/admin/${view}`);render()}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}<br><small>Sign in through the protected admin address.</small></div>`}}
function render(){if(!items.length){$('#content').innerHTML=`<div class="empty">No ${labels[view].toLowerCase()} yet.</div>`;return}$('#content').innerHTML=items.map(x=>{const title=x.title||x.name||(x.document_type==='invoice'?'Invoice':'Quotation')+' '+x.document_number;const prop=[x.location,x.bedrooms?`${x.bedrooms} bed`:null,x.bathrooms?`${x.bathrooms} bath`:null,x.land_area||null,x.parking?'Parking':null].filter(Boolean).join(' · ');const meta=view==='properties'?prop:view==='finance'?`${esc(x.client_name)} · ${esc(x.currency)} ${Number(x.total||0).toLocaleString()} · ${esc(x.issue_date)}`:esc(x.location||x.category||x.phone);return `<article class="item"><div><span class="badge">${esc(x.status)}</span><h3>${esc(title)}</h3><div class="meta">${meta} · ${esc(x.created_at)}</div></div><div class="item-actions">${view==='enquiries'?`<button data-done="${x.id}">Mark handled</button>`:`${view==='finance'?`<button data-print="${x.id}">Print</button>`:''}<button data-edit="${x.id}">Edit</button><button data-delete="${x.id}">Delete</button>`}</div></article>`}).join('')}
const image=x=>`<div class="field"><label>Image URL</label><input name="image_url" value="${esc(x.image_url)}"></div><div class="field"><label>Or upload an image</label><input type="file" name="image_file" accept="image/*"></div>`;
function propertyFields(x){return `<div class="field"><label>Title</label><input name="title" required value="${esc(x.title)}"></div><div class="row"><div class="field"><label>Purpose</label><select name="purpose"><option value="sale">For sale</option><option value="rent">For rent</option><option value="investment">Investment</option></select></div><div class="field"><label>Property type</label><input name="property_type" value="${esc(val(x,'property_type','House'))}"></div></div><div class="row"><div class="field"><label>Location</label><input name="location" required value="${esc(x.location)}"></div><div class="field"><label>Price</label><input name="price" value="${esc(x.price)}"></div></div><div class="row three"><div class="field"><label>Bedrooms</label><input type="number" min="0" name="bedrooms" value="${esc(val(x,'bedrooms',0))}"></div><div class="field"><label>Bathrooms</label><input type="number" min="0" name="bathrooms" value="${esc(val(x,'bathrooms',0))}"></div><div class="field"><label>Toilets</label><input type="number" min="0" name="toilets" value="${esc(val(x,'toilets',0))}"></div></div><div class="row"><div class="field"><label>Land area</label><input name="land_area" placeholder="e.g. 0.25 acre or 650 m²" value="${esc(x.land_area)}"></div><div class="field"><label>Plot dimensions</label><input name="dimensions" placeholder="e.g. 70 × 100 ft" value="${esc(x.dimensions)}"></div></div><div class="row"><div class="field"><label>Furnishing</label><select name="furnishing"><option>Unfurnished</option><option>Semi-furnished</option><option>Fully furnished</option></select></div><div class="field"><label>Parking spaces</label><input type="number" min="0" name="parking_spaces" value="${esc(val(x,'parking_spaces',0))}"></div></div><div class="field check"><label><input type="checkbox" name="parking" ${x.parking?'checked':''}> Parking available</label></div><div class="field"><label>Amenities</label><input name="amenities" placeholder="Pool, security, fitted kitchen, borehole…" value="${esc(x.amenities)}"></div><div class="field"><label>Description</label><textarea name="description" required rows="4">${esc(x.description)}</textarea></div>${image(x)}<div class="row"><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="sold">Sold</option><option value="rented">Rented</option></select></div><div class="field check"><label><input type="checkbox" name="featured" ${x.featured?'checked':''}> Featured property</label></div></div>`}
function postFields(x){return `<div class="field"><label>Title</label><input name="title" required value="${esc(x.title)}"></div><div class="field"><label>Category</label><input name="category" value="${esc(x.category)}"></div><div class="field"><label>Excerpt</label><textarea name="excerpt" required>${esc(x.excerpt)}</textarea></div><div class="field"><label>Article</label><textarea name="content" required rows="7">${esc(x.content)}</textarea></div>${image(x)}<div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option></select></div>`}
function lineRow(x={}){return `<div class="line-row"><input class="line-description" placeholder="Description" value="${esc(x.description)}"><input class="line-quantity" type="number" min="0" step="0.01" placeholder="Qty" value="${esc(val(x,'quantity',1))}"><input class="line-rate" type="number" min="0" step="0.01" placeholder="Rate" value="${esc(val(x,'rate',0))}"><button type="button" class="remove-line">×</button></div>`}
function financeFields(x){let rows=[];try{rows=JSON.parse(x.line_items||'[]')}catch{}if(!rows.length)rows=[{description:'',quantity:1,rate:0}];return `<div class="row"><div class="field"><label>Document type</label><select name="document_type"><option value="quotation">Quotation</option><option value="invoice">Invoice</option></select></div><div class="field"><label>Document number</label><input name="document_number" placeholder="Auto-generated when blank" value="${esc(x.document_number)}"></div></div><div class="field"><label>Client name</label><input name="client_name" required value="${esc(x.client_name)}"></div><div class="row"><div class="field"><label>Client email</label><input type="email" name="client_email" value="${esc(x.client_email)}"></div><div class="field"><label>Client phone</label><input name="client_phone" value="${esc(x.client_phone)}"></div></div><div class="field"><label>Client address</label><textarea name="client_address">${esc(x.client_address)}</textarea></div><div class="row three"><div class="field"><label>Issue date</label><input type="date" name="issue_date" value="${esc(x.issue_date||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="${esc(x.due_date)}"></div><div class="field"><label>Currency</label><select name="currency"><option value="GHS">GHS</option><option value="USD">USD</option></select></div></div><label>Line items</label><div id="line-items">${rows.map(lineRow).join('')}</div><button type="button" id="add-line" class="secondary">+ Add item</button><div class="row"><div class="field"><label>Tax rate (%)</label><input type="number" min="0" step="0.01" name="tax_rate" value="${esc(val(x,'tax_rate',0))}"></div><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="sent">Sent</option><option value="accepted">Accepted</option><option value="paid">Paid</option><option value="overdue">Overdue</option><option value="cancelled">Cancelled</option></select></div></div><div class="field"><label>Notes / payment instructions</label><textarea name="notes" rows="3">${esc(x.notes)}</textarea></div>`}
function fields(x={}){return view==='properties'?propertyFields(x):view==='posts'?postFields(x):financeFields(x)}
function openEditor(x={}){$('#editor-title').textContent=`${x.id?'Edit':'Add'} ${view==='properties'?'property':view==='posts'?'post':'financial document'}`;$('#fields').innerHTML=fields(x);$('#editor-form').elements.id.value=x.id||'';for(const k of ['purpose','status','furnishing','document_type','currency'])if(x[k]&&$('#editor-form').elements[k])$('#editor-form').elements[k].value=x[k];if(view==='finance')$('#add-line').onclick=()=>$('#line-items').insertAdjacentHTML('beforeend',lineRow());$('#editor').showModal()}
function printFinance(x){let rows=[];try{rows=JSON.parse(x.line_items||'[]')}catch{}const w=open('','_blank');w.document.write(`<!doctype html><title>${esc(x.document_number)}</title><style>body{font:15px Arial;max-width:800px;margin:40px auto;color:#171914}header{display:flex;justify-content:space-between;border-bottom:3px solid #c89b4a;padding-bottom:20px}h1{font:36px Georgia;margin:0;text-transform:uppercase}table{width:100%;border-collapse:collapse;margin:35px 0}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.number{text-align:right}.totals{margin-left:auto;width:320px}.totals p{display:flex;justify-content:space-between}.grand{font-size:20px;font-weight:bold;border-top:2px solid #171914;padding-top:10px}@media print{button{display:none}}</style><header><div><strong>JOYREIGNS REALTORS</strong><p>Adenta, Accra · +233 55 247 5643</p></div><div><h1>${esc(x.document_type)}</h1><p>${esc(x.document_number)}</p></div></header><h3>Bill to</h3><p>${esc(x.client_name)}<br>${esc(x.client_address)}<br>${esc(x.client_email)} · ${esc(x.client_phone)}</p><p>Issue date: ${esc(x.issue_date)}${x.due_date?` · Due: ${esc(x.due_date)}`:''}</p><table><thead><tr><th>Description</th><th>Qty</th><th class="number">Rate</th><th class="number">Amount</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.quantity}</td><td class="number">${esc(x.currency)} ${Number(i.rate).toFixed(2)}</td><td class="number">${esc(x.currency)} ${(i.quantity*i.rate).toFixed(2)}</td></tr>`).join('')}</tbody></table><div class="totals"><p><span>Subtotal</span><span>${esc(x.currency)} ${Number(x.subtotal).toFixed(2)}</span></p><p><span>Tax (${Number(x.tax_rate)}%)</span><span>${esc(x.currency)} ${Number(x.tax_amount).toFixed(2)}</span></p><p class="grand"><span>Total</span><span>${esc(x.currency)} ${Number(x.total).toFixed(2)}</span></p></div><p>${esc(x.notes)}</p><button onclick="print()">Print / Save PDF</button>`);w.document.close()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelector('nav .active').classList.remove('active');b.classList.add('active');view=b.dataset.view;$('#title').textContent=labels[view];$('#new').style.display=view==='enquiries'?'none':'';$('#new').textContent=`+ Add ${view==='properties'?'property':view==='posts'?'post':'document'}`;load()});
$('#new').onclick=()=>openEditor();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>$('#editor').close());
$('#fields').onclick=e=>{if(e.target.classList.contains('remove-line'))e.target.closest('.line-row').remove()};
$('#content').onclick=async e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete,done=e.target.dataset.done,print=e.target.dataset.print;if(edit)openEditor(items.find(x=>x.id==edit));if(print)printFinance(items.find(x=>x.id==print));if(del&&confirm('Delete this item?')){await api(`/api/admin/${view}/${del}`,{method:'DELETE'});notify('Deleted');load()}if(done){await api(`/api/admin/enquiries/${done}`,{method:'PATCH',body:JSON.stringify({status:'handled'})});notify('Enquiry updated');load()}};
$('#editor-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),file=f.get('image_file'),v=Object.fromEntries(f);delete v.image_file;v.featured=f.has('featured');v.parking=f.has('parking');if(view==='finance')v.line_items=[...document.querySelectorAll('.line-row')].map(r=>({description:r.querySelector('.line-description').value,quantity:r.querySelector('.line-quantity').value,rate:r.querySelector('.line-rate').value}));const id=v.id;delete v.id;if(file&&file.size){const upload=new FormData();upload.append('file',file);const r=await fetch('/api/admin/upload',{method:'POST',body:upload}),data=await r.json();if(!r.ok)throw new Error(data.error||'Upload failed');v.image_url=data.url}await api(`/api/admin/${view}${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(v)});$('#editor').close();notify('Saved successfully');load()}catch(err){notify(err.message)}};load();
